 "content": "def transform(grid):
    # The bottom row encodes a cyclic sequence; locate each marker color
    # in that sequence and copy the sequence, rotated to begin at marker.
    g = [row[:] for row in grid]
    seq = [x for x in g[-1] if x != 0]
    if not seq:
        return g
    for r, row in enumerate(grid[:-1]):
        for c, color in enumerate(row):
            if color and color in seq:
                i = seq.index(color)
                for k, value in enumerate(seq):
                    if c + k < len(g[r]):
                        g[r][c+k] = seq[(i+k) % len(seq)]
    return g

